26→function makeAdapters() {
27→  return [
28→    ['claude', () => new ClaudeSessionCli({ cmd: process.execPath, args: [FAKE_CLAUDE], killGraceMs: 20 }), 'HOLD_UNTIL_INTERRUPT'],
29→    ['codex', () => new CodexAppServerCli({ cmd: process.execPath, args: [FAKE_CODEX, '--serve'], requestTimeoutMs: 500, versionProbe: () => 'fake' }), 'FAKE:STAY_OPEN'],
30→    ['grok', () => new GrokAcpCli({ cmd: process.execPath, args: [FAKE_GROK, '--serve'], requestTimeoutMs: 500, versionProbe: () => 'fake' }), 'FAKE:STAY_OPEN'],
31→  ];
32→}
