34→function collect(cli) {
35→  const events = [];
36→  cli.onEvent((e) => events.push(e));
37→  return events;
38→}
39→
40→function killPids(events) {
41→  for (const e of events) {
42→    const pid = e.payload?.pid;
43→    if (!pid) continue;
44→    try { process.kill(-pid, 'SIGKILL'); } catch {}
45→  }
46→}
