48→function stubAdapter(over = {}) {
49→  const calls = { prompts: [] };
50→  const a = {
51→    calls, cb: null,
52→    onEvent(cb) { this.cb = cb; },
53→    emit(kind, worker, payload = {}) { this.cb?.({ worker, harness: 'stub@1', turnEpoch: 1, kind, actor: 'worker', payload }); },
54→    card: () => ({ harness: 'stub', version: '1', authPosture: 'none', concurrencyCeiling: 4, maxContext: 1000, verbs: { spawn: 'native', prompt: 'native', steer: 'native', interrupt: 'native', approve: 'native', answer: 'native', kill: 'native', pause: 'unsupported' } }),
55→    spawn: over.spawn ?? (async () => ({ ok: true })),
56→    prompt: over.prompt ?? (async (_w, msg) => { calls.prompts.push(msg); return { ok: true }; }),
57→    interrupt: over.interrupt ?? (async () => ({ ok: true })),
58→    kill: over.kill ?? (async () => ({ ok: true })),
59→    approve: async () => ({ ok: true }), answer: async () => ({ ok: true }),
60→  };
61→  return a;
62→}
