64→function makeCoordinator(a, opts = {}) {
65→  const log = new Log(mkdtempSync(join(tmpdir(), 'p101-log-')));
66→  const worktrees = opts.worktrees ?? {
67→    create: async () => ({ path: mkdtempSync(join(tmpdir(), 'p101-wt-')) }),
68→    capture: async () => ({ sha: 'x' }), createVerifyWorktree: async () => ({ path: tmpdir() }),
69→    removeVerifyWorktree: async () => {}, remove: async () => {}, reconcile: async () => {},
70→  };
71→  const build = () => new Coordinator({
72→    log, fences: new FenceTable(), adapters: { v: a }, worktrees,
73→    referee: async () => ({ reverified: true, observedExit: 0 }), route: () => 'v',
74→    approvalTimeoutMs: 100, stopDeadlineMs: opts.stopDeadlineMs ?? 100,
75→  });
