80→test('SC12: kill while each session adapter awaits worktree readiness prevents child creation', async (t) => {
81→  for (const [name, make, marker] of makeAdapters()) {
82→    const gate = deferred();
83→    const cli = make();
84→    const events = collect(cli);
85→    t.after(() => killPids(events));
86→    const spawning = cli.spawn(`${name}-pending`, brief(marker), { worktreeReady: gate.promise });
87→    await sleep(5);
88→    await cli.kill(`${name}-pending`);
89→    gate.resolve({ path: mkdtempSync(join(tmpdir(), `p101-${name}-`)) });
90→    const ack = await spawning;
91→    await sleep(30);
92→    assert.equal(ack.ok, false, `${name}: cancelled pending spawn must refuse`);
93→    assert.equal(events.some((e) => e.kind === 'lifecycle.spawned'), false, `${name}: no child/session may appear after kill`);
94→    assert.equal(events.filter((e) => e.kind === 'kill.confirmed').length, 1, `${name}: pending kill must confirm exactly once`);
95→  }
96→});
