116→test('SC12: same-worker spawn reservation is atomic across worktreeReady for every session adapter', async (t) => {
117→  for (const [name, make] of makeAdapters()) {
118→    const gate = deferred();
119→    const cli = make();
120→    const events = collect(cli);
121→    t.after(() => killPids(events));
122→    try {
123→      const p1 = cli.spawn(`${name}-dupe`, brief('ordinary'), { worktreeReady: gate.promise });
124→      const p2 = cli.spawn(`${name}-dupe`, brief('ordinary'), { worktreeReady: gate.promise });
125→      gate.resolve({ path: mkdtempSync(join(tmpdir(), `p101-${name}-dupe-`)) });
126→      const acks = await Promise.all([p1, p2]);
127→      assert.equal(acks.filter((a) => a.ok).length, 1, `${name}: exactly one spawn owns the worker`);
128→      for (let i = 0; i < 50 && events.filter((e) => e.kind === 'lifecycle.spawned').length < 1; i += 1) await sleep(5);
