1→// index.mjs — the public entry point. `createDriver()` assembles the whole fleet driver
2→// (log + fences + worktree manager + trust gate + router + story + coordinator) into one
3→// runnable object, wiring the real modules to the coordinator's dependency contract.
4→// This is the "how to run the whole thing" — a program (or your CLI agent, over MCP later)
5→// calls the coordinator's 8 commands; everything underneath is deterministic code.
6→
7→import { join, basename } from 'node:path';
8→import { execFileSync } from 'node:child_process';
9→import { rmSync } from 'node:fs';
10→
11→import { Log } from './log.mjs';
12→import { FenceTable } from './fence.mjs';
13→import { Coordinator } from './coordinator.mjs';
14→import * as worktreeMod from './worktree.mjs';
15→import { verify, accept } from './referee.mjs';
16→import { AdaptiveRouter } from './router.mjs';
17→import { StoryCompiler } from './story.mjs';
18→
19→export { Coordinator } from './coordinator.mjs';
20→export { MockAdapter, CodexAdapter, ClaudeAdapter, GlmAdapter } from './adapter.mjs';
21→// SC2: the session tier IS the product surface — constructible from the entry point.
22→export { ClaudeSessionCli, GlmSessionCli } from './claude-session.mjs';
23→export { CodexAppServerCli } from './codex-appserver.mjs';
24→export { GrokAcpCli } from './grok-acp.mjs';
25→export { createBrief } from './messages.mjs';
26→export { verify, accept } from './referee.mjs';
27→export { AdaptiveRouter } from './router.mjs';
28→
29→/** worktree.mjs's real functions wrapped into the coordinator's manager interface. */
30→function worktreeManager(repoRoot) {
31→  return {
32→    async create(taskId) {
33→      const base = await worktreeMod.pinBaseSha(repoRoot, {});
34→      const r = await worktreeMod.createFromBase(repoRoot, taskId, base.sha, {});
35→      return { path: r.dir, branch: r.branch, baseSha: r.baseSha };
36→    },
37→    async capture(worktreePath, opts = {}) { return worktreeMod.captureCommit(repoRoot, basename(worktreePath), { vendor: opts.vendor }); },
38→    async createVerifyWorktree(taskId, sha) {
39→      const r = await worktreeMod.freshVerifySandbox(repoRoot, taskId, sha, {});
40→      return { path: r.dir ?? r.path };
41→    },
42→    async removeVerifyWorktree(verifyPath) {
43→      try { execFileSync('git', ['worktree', 'remove', '--force', verifyPath], { cwd: repoRoot, stdio: 'ignore' }); } catch { /* noop */ }
44→      try { rmSync(verifyPath, { recursive: true, force: true }); } catch { /* noop */ }
45→    },
46→    async remove(taskId) { try { await worktreeMod.reap(repoRoot, taskId, { force: true }); } catch { /* noop */ } },
47→    async reconcile() { try { await worktreeMod.reconcile(repoRoot, []); } catch { /* noop */ } },
48→  };
49→}
